-- Curated real and fictional size comparisons; keep all older versions.
BEGIN;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-0","version":9,"kind":"scale","prompt":"How big is Death Star I?","target":{"name":"Death Star I","dimension":"equatorial diameter","shape":"sourced:death-star"},"reference":{"name":"Earth","dimension":"equatorial diameter","shape":"sourced:earth","measure":"1.2756e+07 m"},"bounds":[0.002,1.4],"answer":0.012543117,"explanation":"Death Star I: 160000 m (equatorial diameter). Earth: 1.2756e+07 m (equatorial diameter).\nThe first Death Star in A New Hope: the current official reference gives a diameter of 160 km. Fictional.\nEarth’s equatorial diameter is about 12,756 km.","sources":["https://www.starwars.com/news/star-wars-inside-intel-the-death-star","https://science.nasa.gov/earth/facts/"]},{"id":"size-v9-1","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.0681818182,"explanation":"AT-AT walker: 22.5 m (height). Eiffel Tower: 330 m (height, antenna included).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.starwars.com/databank/at-at-walker","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-2","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.964028777,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). Millennium Falcon: 34.75 m (overall length).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-3","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus","measure":"12 m"},"bounds":[0.002,1.4],"answer":1.0,"explanation":"Tyrannosaurus rex: 12 m (adult length). Bus: 12 m (reference length).\nAMNH gives an adult T. rex length of about 12 m.\nThe bus is a fixed 12 m reference; vehicle models have different lengths.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","Reference chosen for comparison: a 12 m bus."]},{"id":"size-v9-4","version":9,"kind":"scale","prompt":"How big is Banana?","target":{"name":"Banana","dimension":"reference length","shape":"sourced:banana"},"reference":{"name":"Person","dimension":"reference height","shape":"sourced:human","measure":"1.75 m"},"bounds":[0.002,1.4],"answer":0.1028571429,"explanation":"Banana: 0.18 m (reference length). Person: 1.75 m (reference height).\nAn 18 cm banana reference. Real bananas vary.\nThe person is a fixed 1.75 m reference, not a claim about average human height.","sources":["Reference chosen for comparison: an 18 cm banana.","Reference chosen for comparison: a 1.75 m person."]}]'::jsonb WHERE game='how-much-ish' AND slot=1;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-5","version":9,"kind":"scale","prompt":"How big is The Moon?","target":{"name":"The Moon","dimension":"mean diameter","shape":"sourced:moon"},"reference":{"name":"Earth","dimension":"equatorial diameter","shape":"sourced:earth","measure":"1.2756e+07 m"},"bounds":[0.002,1.4],"answer":0.2724051427,"explanation":"The Moon: 3.4748e+06 m (mean diameter). Earth: 1.2756e+07 m (equatorial diameter).\nThe Moon’s mean diameter is about 3,474.8 km.\nEarth’s equatorial diameter is about 12,756 km.","sources":["https://science.nasa.gov/wp-content/uploads/2023/05/ladee-press-kit-08292013.pdf","https://science.nasa.gov/earth/facts/"]},{"id":"size-v9-6","version":9,"kind":"scale","prompt":"How big is Saturn V?","target":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.3351515152,"explanation":"Saturn V: 110.6 m (height with Apollo spacecraft). Eiffel Tower: 330 m (height, antenna included).\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-7","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.0777777778,"explanation":"Person: 1.75 m (reference height). AT-AT walker: 22.5 m (height).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-8","version":9,"kind":"scale","prompt":"How big is Millennium Falcon?","target":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.3188073394,"explanation":"Millennium Falcon: 34.75 m (overall length). International Space Station: 109 m (end-to-end span).\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.starwars.com/databank/millennium-falcon","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-9","version":9,"kind":"scale","prompt":"How big is Imperial Star Destroyer?","target":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer"},"reference":{"name":"Darth Vader’s Executor","dimension":"length","shape":"sourced:executor","measure":"19000 m"},"bounds":[0.002,1.4],"answer":0.0842105263,"explanation":"Imperial Star Destroyer: 1600 m (length). Darth Vader’s Executor: 19000 m (length).\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.\nThe Executor Super Star Destroyer is 19 km long. Fictional; shown from above.","sources":["https://www.starwars.com/databank/imperial-star-destroyer/","https://www.starwars.com/databank/executor"]}]'::jsonb WHERE game='how-much-ish' AND slot=2;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-10","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.2444444444,"explanation":"Male giraffe: 5.5 m (upper adult height). AT-AT walker: 22.5 m (height).\nMale giraffes can reach about 5.5 m tall.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-11","version":9,"kind":"scale","prompt":"How big is Golf ball?","target":{"name":"Golf ball","dimension":"minimum permitted diameter","shape":"sourced:golf-ball"},"reference":{"name":"Banana","dimension":"reference length","shape":"sourced:banana","measure":"0.18 m"},"bounds":[0.002,1.4],"answer":0.2370555556,"explanation":"Golf ball: 0.04267 m (minimum permitted diameter). Banana: 0.18 m (reference length).\nThe equipment rules set a minimum diameter of 42.67 mm. This board uses that minimum.\nAn 18 cm banana reference. Real bananas vary.","sources":["https://www.randa.org/roe/the-rules-of-equipment/part-4-conformance-of-balls","Reference chosen for comparison: an 18 cm banana."]},{"id":"size-v9-12","version":9,"kind":"scale","prompt":"How big is Statue of Liberty?","target":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.8407775769,"explanation":"Statue of Liberty: 92.99 m (height, pedestal included). Saturn V: 110.6 m (height with Apollo spacecraft).\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-13","version":9,"kind":"scale","prompt":"How big is Mars?","target":{"name":"Mars","dimension":"equatorial diameter","shape":"sourced:mars"},"reference":{"name":"Earth","dimension":"equatorial diameter","shape":"sourced:earth","measure":"1.2756e+07 m"},"bounds":[0.002,1.4],"answer":0.5324553151,"explanation":"Mars: 6.792e+06 m (equatorial diameter). Earth: 1.2756e+07 m (equatorial diameter).\nMars’s equatorial diameter is about 6,792 km.\nEarth’s equatorial diameter is about 12,756 km.","sources":["https://science.nasa.gov/solar-system/planets/planet-sizes-and-locations-in-our-solar-system/","https://science.nasa.gov/earth/facts/"]},{"id":"size-v9-14","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.4607977992,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). Airbus A380: 72.7 m (overall aircraft length).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]}]'::jsonb WHERE game='how-much-ish' AND slot=3;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-15","version":9,"kind":"scale","prompt":"How big is Darth Vader’s Executor?","target":{"name":"Darth Vader’s Executor","dimension":"length","shape":"sourced:executor"},"reference":{"name":"Death Star I","dimension":"equatorial diameter","shape":"sourced:death-star","measure":"160000 m"},"bounds":[0.002,1.4],"answer":0.11875,"explanation":"Darth Vader’s Executor: 19000 m (length). Death Star I: 160000 m (equatorial diameter).\nThe Executor Super Star Destroyer is 19 km long. Fictional; shown from above.\nThe first Death Star in A New Hope: the current official reference gives a diameter of 160 km. Fictional.","sources":["https://www.starwars.com/databank/executor","https://www.starwars.com/news/star-wars-inside-intel-the-death-star"]},{"id":"size-v9-16","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.2419615012,"explanation":"AT-AT walker: 22.5 m (height). Statue of Liberty: 92.99 m (height, pedestal included).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.starwars.com/databank/at-at-walker","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-17","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.345323741,"explanation":"Tyrannosaurus rex: 12 m (adult length). Millennium Falcon: 34.75 m (overall length).\nAMNH gives an adult T. rex length of about 12 m.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-18","version":9,"kind":"scale","prompt":"How big is US quarter?","target":{"name":"US quarter","dimension":"coin diameter","shape":"sourced:quarter"},"reference":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note","measure":"0.156 m"},"bounds":[0.002,1.4],"answer":0.1555128205,"explanation":"US quarter: 0.02426 m (coin diameter). US dollar note: 0.156 m (approximate note length).\nA US quarter has a diameter of 24.26 mm. The profile represents the coin’s outline.\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.","sources":["https://www.usmint.gov/learn/coins-and-medals/circulating-coins/coin-specifications","https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm"]},{"id":"size-v9-19","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus","measure":"12 m"},"bounds":[0.002,1.4],"answer":0.6083333333,"explanation":"African elephant: 7.3 m (upper adult length). Bus: 12 m (reference length).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nThe bus is a fixed 12 m reference; vehicle models have different lengths.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","Reference chosen for comparison: a 12 m bus."]}]'::jsonb WHERE game='how-much-ish' AND slot=4;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-20","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale","measure":"18.3 m"},"bounds":[0.002,1.4],"answer":1.2295081967,"explanation":"AT-AT walker: 22.5 m (height). Humpback whale: 18.3 m (upper adult length).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nHumpbacks can reach about 60 ft (18.3 m).","sources":["https://www.starwars.com/databank/at-at-walker","https://www.fisheries.noaa.gov/species/humpback-whale"]},{"id":"size-v9-21","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.1084990958,"explanation":"Tyrannosaurus rex: 12 m (adult length). Saturn V: 110.6 m (height with Apollo spacecraft).\nAMNH gives an adult T. rex length of about 12 m.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-22","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe","measure":"5.5 m"},"bounds":[0.002,1.4],"answer":0.0283636364,"explanation":"US dollar note: 0.156 m (approximate note length). Male giraffe: 5.5 m (upper adult height).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nMale giraffes can reach about 5.5 m tall.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","https://animals.sandiegozoo.org/animals/giraffe"]},{"id":"size-v9-23","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.0785030648,"explanation":"African elephant: 7.3 m (upper adult length). Statue of Liberty: 92.99 m (height, pedestal included).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-24","version":9,"kind":"scale","prompt":"How big is Gateway Arch?","target":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch"},"reference":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer","measure":"1600 m"},"bounds":[0.002,1.4],"answer":0.12,"explanation":"Gateway Arch: 192 m (height above ground). Imperial Star Destroyer: 1600 m (length).\nThe arch is about 192 m tall and approximately the same width from leg to leg.\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.","sources":["https://www.nps.gov/jeff/faqs.htm","https://www.starwars.com/databank/imperial-star-destroyer/"]}]'::jsonb WHERE game='how-much-ish' AND slot=5;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-25","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.1325757576,"explanation":"Person: 1.75 m (reference height). Hubble telescope: 13.2 m (body length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["Reference chosen for comparison: a 1.75 m person.","https://science.nasa.gov/mission/hubble/observatory/design/"]},{"id":"size-v9-26","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.345323741,"explanation":"Bus: 12 m (reference length). Millennium Falcon: 34.75 m (overall length).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-27","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear","measure":"2.7 m"},"bounds":[0.002,1.4],"answer":0.0577777778,"explanation":"US dollar note: 0.156 m (approximate note length). Polar bear: 2.7 m (upper usual body length).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","https://animals.sandiegozoo.org/animals/polar-bear"]},{"id":"size-v9-28","version":9,"kind":"scale","prompt":"How big is Death Star I?","target":{"name":"Death Star I","dimension":"equatorial diameter","shape":"sourced:death-star"},"reference":{"name":"Mars","dimension":"equatorial diameter","shape":"sourced:mars","measure":"6.792e+06 m"},"bounds":[0.002,1.4],"answer":0.023557126,"explanation":"Death Star I: 160000 m (equatorial diameter). Mars: 6.792e+06 m (equatorial diameter).\nThe first Death Star in A New Hope: the current official reference gives a diameter of 160 km. Fictional.\nMars’s equatorial diameter is about 6,792 km.","sources":["https://www.starwars.com/news/star-wars-inside-intel-the-death-star","https://science.nasa.gov/solar-system/planets/planet-sizes-and-locations-in-our-solar-system/"]},{"id":"size-v9-29","version":9,"kind":"scale","prompt":"How big is Banana?","target":{"name":"Banana","dimension":"reference length","shape":"sourced:banana"},"reference":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant","measure":"7.3 m"},"bounds":[0.002,1.4],"answer":0.0246575342,"explanation":"Banana: 0.18 m (reference length). African elephant: 7.3 m (upper adult length).\nAn 18 cm banana reference. Real bananas vary.\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.","sources":["Reference chosen for comparison: an 18 cm banana.","https://www.worldwildlife.org/species/elephant/african-elephant/"]}]'::jsonb WHERE game='how-much-ish' AND slot=6;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-30","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.1331360947,"explanation":"AT-AT walker: 22.5 m (height). Washington Monument: 169 m (rounded monument height).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.starwars.com/databank/at-at-walker","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-31","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale","measure":"18.3 m"},"bounds":[0.002,1.4],"answer":0.0956284153,"explanation":"Person: 1.75 m (reference height). Humpback whale: 18.3 m (upper adult length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nHumpbacks can reach about 60 ft (18.3 m).","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.fisheries.noaa.gov/species/humpback-whale"]},{"id":"size-v9-32","version":9,"kind":"scale","prompt":"How big is Airbus A380?","target":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.2203030303,"explanation":"Airbus A380: 72.7 m (overall aircraft length). Eiffel Tower: 330 m (height, antenna included).\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-33","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.0286458333,"explanation":"Male giraffe: 5.5 m (upper adult height). Gateway Arch: 192 m (height above ground).\nMale giraffes can reach about 5.5 m tall.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-34","version":9,"kind":"scale","prompt":"How big is Millennium Falcon?","target":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.4779917469,"explanation":"Millennium Falcon: 34.75 m (overall length). Airbus A380: 72.7 m (overall aircraft length).\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://www.starwars.com/databank/millennium-falcon","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]}]'::jsonb WHERE game='how-much-ish' AND slot=7;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-35","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus","measure":"5 m"},"bounds":[0.002,1.4],"answer":0.4,"explanation":"Door: 2 m (reference height). Hippopotamus: 5 m (upper adult length).\nA two-metre door reference; doors vary.\nHippos measure about 3.3–5 m long. This board uses the upper end.","sources":["Reference chosen for comparison: a two-metre door.","https://animals.sandiegozoo.org/animals/hippo"]},{"id":"size-v9-36","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe","measure":"5.5 m"},"bounds":[0.002,1.4],"answer":0.3181818182,"explanation":"Person: 1.75 m (reference height). Male giraffe: 5.5 m (upper adult height).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nMale giraffes can reach about 5.5 m tall.","sources":["Reference chosen for comparison: a 1.75 m person.","https://animals.sandiegozoo.org/animals/giraffe"]},{"id":"size-v9-37","version":9,"kind":"scale","prompt":"How big is Humpback whale?","target":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.1654611212,"explanation":"Humpback whale: 18.3 m (upper adult length). Saturn V: 110.6 m (height with Apollo spacecraft).\nHumpbacks can reach about 60 ft (18.3 m).\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.fisheries.noaa.gov/species/humpback-whale","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-38","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.1682793437,"explanation":"White rhinoceros: 4 m (upper adult length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-39","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.2689393939,"explanation":"Male lion: 3.55 m (large adult length, tail included). Hubble telescope: 13.2 m (body length).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://animals.sandiegozoo.org/animals/lion","https://science.nasa.gov/mission/hubble/observatory/design/"]}]'::jsonb WHERE game='how-much-ish' AND slot=8;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-40","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.1744791667,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). Gateway Arch: 192 m (height above ground).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-41","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.0776978417,"explanation":"Polar bear: 2.7 m (upper usual body length). Millennium Falcon: 34.75 m (overall length).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-42","version":9,"kind":"scale","prompt":"How big is Humpback whale?","target":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.0554545455,"explanation":"Humpback whale: 18.3 m (upper adult length). Eiffel Tower: 330 m (height, antenna included).\nHumpbacks can reach about 60 ft (18.3 m).\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.fisheries.noaa.gov/species/humpback-whale","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-43","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.12,"explanation":"Polar bear: 2.7 m (upper usual body length). AT-AT walker: 22.5 m (height).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-44","version":9,"kind":"scale","prompt":"How big is Gateway Arch?","target":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.5818181818,"explanation":"Gateway Arch: 192 m (height above ground). Eiffel Tower: 330 m (height, antenna included).\nThe arch is about 192 m tall and approximately the same width from leg to leg.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.nps.gov/jeff/faqs.htm","https://www.toureiffel.paris/en/the-monument/key-figures"]}]'::jsonb WHERE game='how-much-ish' AND slot=9;
UPDATE ledger_private.game_starter_packs SET questions='[{"id":"size-v9-45","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale","measure":"18.3 m"},"bounds":[0.002,1.4],"answer":0.7213114754,"explanation":"Hubble telescope: 13.2 m (body length). Humpback whale: 18.3 m (upper adult length).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nHumpbacks can reach about 60 ft (18.3 m).","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.fisheries.noaa.gov/species/humpback-whale"]},{"id":"size-v9-46","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale","measure":"33.5 m"},"bounds":[0.002,1.4],"answer":0.052238806,"explanation":"Person: 1.75 m (reference height). Antarctic blue whale: 33.5 m (upper adult length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.fisheries.noaa.gov/species/blue-whale"]},{"id":"size-v9-47","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant","measure":"7.3 m"},"bounds":[0.002,1.4],"answer":0.021369863,"explanation":"US dollar note: 0.156 m (approximate note length). African elephant: 7.3 m (upper adult length).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","https://www.worldwildlife.org/species/elephant/african-elephant/"]},{"id":"size-v9-48","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.0320976492,"explanation":"Male lion: 3.55 m (large adult length, tail included). Saturn V: 110.6 m (height with Apollo spacecraft).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://animals.sandiegozoo.org/animals/lion","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-49","version":9,"kind":"scale","prompt":"How big is Millennium Falcon?","target":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.2056213018,"explanation":"Millennium Falcon: 34.75 m (overall length). Washington Monument: 169 m (rounded monument height).\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.starwars.com/databank/millennium-falcon","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]}]'::jsonb WHERE game='how-much-ish' AND slot=10;
CREATE FUNCTION ledger_private.size_editorial_version() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path='' AS $$ SELECT 9;$$;
CREATE OR REPLACE FUNCTION public.utilities_trivia_capabilities() RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$ SELECT jsonb_build_object('version',7,'games',7,'groups',true,'size_objects',35,'online_sync',true,'online_seed',1,'archive',true,'grid_puzzles',true,'photo_silhouettes',true,'passport_editorial',2,'timed_grids',true,'size_editorial',9);$$;
COMMIT;
