INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',0,9,'[{"id":"size-v9-50","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.1650618982,"explanation":"Tyrannosaurus rex: 12 m (adult length). Airbus A380: 72.7 m (overall aircraft length).\nAMNH gives an adult T. rex length of about 12 m.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-51","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.0366972477,"explanation":"White rhinoceros: 4 m (upper adult length). International Space Station: 109 m (end-to-end span).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-52","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.0550206327,"explanation":"White rhinoceros: 4 m (upper adult length). Airbus A380: 72.7 m (overall aircraft length).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-53","version":9,"kind":"scale","prompt":"How big is Humpback whale?","target":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.1082840237,"explanation":"Humpback whale: 18.3 m (upper adult length). Washington Monument: 169 m (rounded monument height).\nHumpbacks can reach about 60 ft (18.3 m).\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.fisheries.noaa.gov/species/humpback-whale","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-54","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.056969697,"explanation":"Whale shark: 18.8 m (record measured length). Eiffel Tower: 330 m (height, antenna included).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.toureiffel.paris/en/the-monument/key-figures"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',1,9,'[{"id":"size-v9-55","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.9465713084,"explanation":"AT-AT walker: 22.5 m (height). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://www.starwars.com/databank/at-at-walker","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-56","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.1171875,"explanation":"AT-AT walker: 22.5 m (height). Gateway Arch: 192 m (height above ground).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.starwars.com/databank/at-at-walker","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-57","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.0841396719,"explanation":"Door: 2 m (reference height). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nA two-metre door reference; doors vary.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["Reference chosen for comparison: a two-metre door.","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-58","version":9,"kind":"scale","prompt":"How big is Airbus A380?","target":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.3786458333,"explanation":"Airbus A380: 72.7 m (overall aircraft length). Gateway Arch: 192 m (height above ground).\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-59","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark","measure":"18.8 m"},"bounds":[0.002,1.4],"answer":0.7021276596,"explanation":"Hubble telescope: 13.2 m (body length). Whale shark: 18.8 m (record measured length).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.georgiaaquarium.org/animal/whale-shark/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',2,9,'[{"id":"size-v9-60","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.5048380311,"explanation":"Bus: 12 m (reference length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-61","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.1084990958,"explanation":"Bus: 12 m (reference length). Saturn V: 110.6 m (height with Apollo spacecraft).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["Reference chosen for comparison: a 12 m bus.","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-62","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.0591461447,"explanation":"Male giraffe: 5.5 m (upper adult height). Statue of Liberty: 92.99 m (height, pedestal included).\nMale giraffes can reach about 5.5 m tall.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-63","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale","measure":"33.5 m"},"bounds":[0.002,1.4],"answer":0.3940298507,"explanation":"Hubble telescope: 13.2 m (body length). Antarctic blue whale: 33.5 m (upper adult length).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.fisheries.noaa.gov/species/blue-whale"]},{"id":"size-v9-64","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.3028933092,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). Saturn V: 110.6 m (height with Apollo spacecraft).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',3,9,'[{"id":"size-v9-65","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.2187070151,"explanation":"Male sperm whale: 15.9 m (mature adult length). Airbus A380: 72.7 m (overall aircraft length).\nMature males reach about 52 ft (15.9 m); females are smaller.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-66","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.0452079566,"explanation":"Hippopotamus: 5 m (upper adult length). Saturn V: 110.6 m (height with Apollo spacecraft).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://animals.sandiegozoo.org/animals/hippo","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-67","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.0669724771,"explanation":"African elephant: 7.3 m (upper adult length). International Space Station: 109 m (end-to-end span).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-68","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.1577777778,"explanation":"Male lion: 3.55 m (large adult length, tail included). AT-AT walker: 22.5 m (height).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://animals.sandiegozoo.org/animals/lion","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-69","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.2021722766,"explanation":"Whale shark: 18.8 m (record measured length). Statue of Liberty: 92.99 m (height, pedestal included).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',4,9,'[{"id":"size-v9-70","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.0828125,"explanation":"Male sperm whale: 15.9 m (mature adult length). Gateway Arch: 192 m (height above ground).\nMature males reach about 52 ft (15.9 m); females are smaller.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-71","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.8355555556,"explanation":"Whale shark: 18.8 m (record measured length). AT-AT walker: 22.5 m (height).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-72","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus","measure":"12 m"},"bounds":[0.002,1.4],"answer":0.2958333333,"explanation":"Male lion: 3.55 m (large adult length, tail included). Bus: 12 m (reference length).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nThe bus is a fixed 12 m reference; vehicle models have different lengths.","sources":["https://animals.sandiegozoo.org/animals/lion","Reference chosen for comparison: a 12 m bus."]},{"id":"size-v9-73","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.0488308116,"explanation":"Male lion: 3.55 m (large adult length, tail included). Airbus A380: 72.7 m (overall aircraft length).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://animals.sandiegozoo.org/animals/lion","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-74","version":9,"kind":"scale","prompt":"How big is US quarter?","target":{"name":"US quarter","dimension":"coin diameter","shape":"sourced:quarter"},"reference":{"name":"Banana","dimension":"reference length","shape":"sourced:banana","measure":"0.18 m"},"bounds":[0.002,1.4],"answer":0.1347777778,"explanation":"US quarter: 0.02426 m (coin diameter). Banana: 0.18 m (reference length).\nA US quarter has a diameter of 24.26 mm. The profile represents the coin’s outline.\nAn 18 cm banana reference. Real bananas vary.","sources":["https://www.usmint.gov/learn/coins-and-medals/circulating-coins/coin-specifications","Reference chosen for comparison: an 18 cm banana."]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',5,9,'[{"id":"size-v9-75","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.038176148,"explanation":"Male lion: 3.55 m (large adult length, tail included). Statue of Liberty: 92.99 m (height, pedestal included).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://animals.sandiegozoo.org/animals/lion","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-76","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.1021582734,"explanation":"Male lion: 3.55 m (large adult length, tail included). Millennium Falcon: 34.75 m (overall length).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://animals.sandiegozoo.org/animals/lion","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-77","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.2100719424,"explanation":"African elephant: 7.3 m (upper adult length). Millennium Falcon: 34.75 m (overall length).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-78","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.5048380311,"explanation":"Tyrannosaurus rex: 12 m (adult length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nAMNH gives an adult T. rex length of about 12 m.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-79","version":9,"kind":"scale","prompt":"How big is Eiffel Tower?","target":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower"},"reference":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer","measure":"1600 m"},"bounds":[0.002,1.4],"answer":0.20625,"explanation":"Eiffel Tower: 330 m (height, antenna included). Imperial Star Destroyer: 1600 m (length).\nThe Eiffel Tower is 330 m tall including its antenna.\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.","sources":["https://www.toureiffel.paris/en/the-monument/key-figures","https://www.starwars.com/databank/imperial-star-destroyer/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',6,9,'[{"id":"size-v9-80","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus","measure":"5 m"},"bounds":[0.002,1.4],"answer":0.0312,"explanation":"US dollar note: 0.156 m (approximate note length). Hippopotamus: 5 m (upper adult length).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nHippos measure about 3.3–5 m long. This board uses the upper end.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","https://animals.sandiegozoo.org/animals/hippo"]},{"id":"size-v9-81","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.04,"explanation":"Hubble telescope: 13.2 m (body length). Eiffel Tower: 330 m (height, antenna included).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-82","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale","measure":"33.5 m"},"bounds":[0.002,1.4],"answer":0.671641791,"explanation":"AT-AT walker: 22.5 m (height). Antarctic blue whale: 33.5 m (upper adult length).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.","sources":["https://www.starwars.com/databank/at-at-walker","https://www.fisheries.noaa.gov/species/blue-whale"]},{"id":"size-v9-83","version":9,"kind":"scale","prompt":"How big is Doubles tennis court?","target":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.1238020833,"explanation":"Doubles tennis court: 23.77 m (baseline-to-baseline length). Gateway Arch: 192 m (height above ground).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-84","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant","measure":"7.3 m"},"bounds":[0.002,1.4],"answer":0.2739726027,"explanation":"Door: 2 m (reference height). African elephant: 7.3 m (upper adult length).\nA two-metre door reference; doors vary.\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.","sources":["Reference chosen for comparison: a two-metre door.","https://www.worldwildlife.org/species/elephant/african-elephant/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',7,9,'[{"id":"size-v9-85","version":9,"kind":"scale","prompt":"How big is Humpback whale?","target":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.2517193948,"explanation":"Humpback whale: 18.3 m (upper adult length). Airbus A380: 72.7 m (overall aircraft length).\nHumpbacks can reach about 60 ft (18.3 m).\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://www.fisheries.noaa.gov/species/humpback-whale","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-86","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.6689103912,"explanation":"Male sperm whale: 15.9 m (mature adult length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nMature males reach about 52 ft (15.9 m); females are smaller.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-87","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.1777777778,"explanation":"White rhinoceros: 4 m (upper adult length). AT-AT walker: 22.5 m (height).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-88","version":9,"kind":"scale","prompt":"How big is Banana?","target":{"name":"Banana","dimension":"reference length","shape":"sourced:banana"},"reference":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear","measure":"2.7 m"},"bounds":[0.002,1.4],"answer":0.0666666667,"explanation":"Banana: 0.18 m (reference length). Polar bear: 2.7 m (upper usual body length).\nAn 18 cm banana reference. Real bananas vary.\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.","sources":["Reference chosen for comparison: an 18 cm banana.","https://animals.sandiegozoo.org/animals/polar-bear"]},{"id":"size-v9-89","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.0371389271,"explanation":"Polar bear: 2.7 m (upper usual body length). Airbus A380: 72.7 m (overall aircraft length).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',8,9,'[{"id":"size-v9-90","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark","measure":"18.8 m"},"bounds":[0.002,1.4],"answer":0.6382978723,"explanation":"Bus: 12 m (reference length). Whale shark: 18.8 m (record measured length).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.georgiaaquarium.org/animal/whale-shark/"]},{"id":"size-v9-91","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.0380208333,"explanation":"African elephant: 7.3 m (upper adult length). Gateway Arch: 192 m (height above ground).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-92","version":9,"kind":"scale","prompt":"How big is Humpback whale?","target":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.1967953543,"explanation":"Humpback whale: 18.3 m (upper adult length). Statue of Liberty: 92.99 m (height, pedestal included).\nHumpbacks can reach about 60 ft (18.3 m).\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.fisheries.noaa.gov/species/humpback-whale","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-93","version":9,"kind":"scale","prompt":"How big is Millennium Falcon?","target":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.3141952984,"explanation":"Millennium Falcon: 34.75 m (overall length). Saturn V: 110.6 m (height with Apollo spacecraft).\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.starwars.com/databank/millennium-falcon","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-94","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.181568088,"explanation":"Hubble telescope: 13.2 m (body length). Airbus A380: 72.7 m (overall aircraft length).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]}]'::jsonb);
