INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',11,9,'[{"id":"size-v9-105","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.0247706422,"explanation":"Polar bear: 2.7 m (upper usual body length). International Space Station: 109 m (end-to-end span).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-106","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0236686391,"explanation":"White rhinoceros: 4 m (upper adult length). Washington Monument: 169 m (rounded monument height).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-107","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.7909129154,"explanation":"Whale shark: 18.8 m (record measured length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-108","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0940828402,"explanation":"Male sperm whale: 15.9 m (mature adult length). Washington Monument: 169 m (rounded monument height).\nMature males reach about 52 ft (15.9 m); females are smaller.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-109","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.3787878788,"explanation":"Hippopotamus: 5 m (upper adult length). Hubble telescope: 13.2 m (body length).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://animals.sandiegozoo.org/animals/hippo","https://science.nasa.gov/mission/hubble/observatory/design/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',12,9,'[{"id":"size-v9-110","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.5333333333,"explanation":"Tyrannosaurus rex: 12 m (adult length). AT-AT walker: 22.5 m (height).\nAMNH gives an adult T. rex length of about 12 m.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-111","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros","measure":"4 m"},"bounds":[0.002,1.4],"answer":0.5,"explanation":"Door: 2 m (reference height). White rhinoceros: 4 m (upper adult length).\nA two-metre door reference; doors vary.\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.","sources":["Reference chosen for comparison: a two-metre door.","https://animals.sandiegozoo.org/animals/rhinoceros"]},{"id":"size-v9-112","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex","measure":"12 m"},"bounds":[0.002,1.4],"answer":0.1666666667,"explanation":"Door: 2 m (reference height). Tyrannosaurus rex: 12 m (adult length).\nA two-metre door reference; doors vary.\nAMNH gives an adult T. rex length of about 12 m.","sources":["Reference chosen for comparison: a two-metre door.","https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size"]},{"id":"size-v9-113","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.9090909091,"explanation":"Bus: 12 m (reference length). Hubble telescope: 13.2 m (body length).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["Reference chosen for comparison: a 12 m bus.","https://science.nasa.gov/mission/hubble/observatory/design/"]},{"id":"size-v9-114","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.1151079137,"explanation":"White rhinoceros: 4 m (upper adult length). Millennium Falcon: 34.75 m (overall length).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://www.starwars.com/databank/millennium-falcon"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',13,9,'[{"id":"size-v9-115","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.0458715596,"explanation":"Hippopotamus: 5 m (upper adult length). International Space Station: 109 m (end-to-end span).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://animals.sandiegozoo.org/animals/hippo","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-116","version":9,"kind":"scale","prompt":"How big is Doubles tennis court?","target":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.2149186257,"explanation":"Doubles tennis court: 23.77 m (baseline-to-baseline length). Saturn V: 110.6 m (height with Apollo spacecraft).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-117","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.1458715596,"explanation":"Male sperm whale: 15.9 m (mature adult length). International Space Station: 109 m (end-to-end span).\nMature males reach about 52 ft (15.9 m); females are smaller.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-118","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale","measure":"18.3 m"},"bounds":[0.002,1.4],"answer":0.1092896175,"explanation":"Door: 2 m (reference height). Humpback whale: 18.3 m (upper adult length).\nA two-metre door reference; doors vary.\nHumpbacks can reach about 60 ft (18.3 m).","sources":["Reference chosen for comparison: a two-metre door.","https://www.fisheries.noaa.gov/species/humpback-whale"]},{"id":"size-v9-119","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.0687757909,"explanation":"Hippopotamus: 5 m (upper adult length). Airbus A380: 72.7 m (overall aircraft length).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://animals.sandiegozoo.org/animals/hippo","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',14,9,'[{"id":"size-v9-120","version":9,"kind":"scale","prompt":"How big is Doubles tennis court?","target":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.32696011,"explanation":"Doubles tennis court: 23.77 m (baseline-to-baseline length). Airbus A380: 72.7 m (overall aircraft length).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-121","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale","measure":"15.9 m"},"bounds":[0.002,1.4],"answer":0.7547169811,"explanation":"Bus: 12 m (reference length). Male sperm whale: 15.9 m (mature adult length).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nMature males reach about 52 ft (15.9 m); females are smaller.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.fisheries.noaa.gov/species/sperm-whale"]},{"id":"size-v9-122","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.0260416667,"explanation":"Hippopotamus: 5 m (upper adult length). Gateway Arch: 192 m (height above ground).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://animals.sandiegozoo.org/animals/hippo","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-123","version":9,"kind":"scale","prompt":"How big is Saturn V?","target":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.6544378698,"explanation":"Saturn V: 110.6 m (height with Apollo spacecraft). Washington Monument: 169 m (rounded monument height).\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-124","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus","measure":"12 m"},"bounds":[0.002,1.4],"answer":0.3333333333,"explanation":"White rhinoceros: 4 m (upper adult length). Bus: 12 m (reference length).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nThe bus is a fixed 12 m reference; vehicle models have different lengths.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","Reference chosen for comparison: a 12 m bus."]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',15,9,'[{"id":"size-v9-125","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe","measure":"5.5 m"},"bounds":[0.002,1.4],"answer":0.3636363636,"explanation":"Door: 2 m (reference height). Male giraffe: 5.5 m (upper adult height).\nA two-metre door reference; doors vary.\nMale giraffes can reach about 5.5 m tall.","sources":["Reference chosen for comparison: a two-metre door.","https://animals.sandiegozoo.org/animals/giraffe"]},{"id":"size-v9-126","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.0625,"explanation":"Tyrannosaurus rex: 12 m (adult length). Gateway Arch: 192 m (height above ground).\nAMNH gives an adult T. rex length of about 12 m.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-127","version":9,"kind":"scale","prompt":"How big is Golf ball?","target":{"name":"Golf ball","dimension":"minimum permitted diameter","shape":"sourced:golf-ball"},"reference":{"name":"Person","dimension":"reference height","shape":"sourced:human","measure":"1.75 m"},"bounds":[0.002,1.4],"answer":0.0243828571,"explanation":"Golf ball: 0.04267 m (minimum permitted diameter). Person: 1.75 m (reference height).\nThe equipment rules set a minimum diameter of 42.67 mm. This board uses that minimum.\nThe person is a fixed 1.75 m reference, not a claim about average human height.","sources":["https://www.randa.org/roe/the-rules-of-equipment/part-4-conformance-of-balls","Reference chosen for comparison: a 1.75 m person."]},{"id":"size-v9-128","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.143761302,"explanation":"Male sperm whale: 15.9 m (mature adult length). Saturn V: 110.6 m (height with Apollo spacecraft).\nMature males reach about 52 ft (15.9 m); females are smaller.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-129","version":9,"kind":"scale","prompt":"How big is Statue of Liberty?","target":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.5502366864,"explanation":"Statue of Liberty: 92.99 m (height, pedestal included). Washington Monument: 169 m (rounded monument height).\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',16,9,'[{"id":"size-v9-130","version":9,"kind":"scale","prompt":"How big is Airbus A380?","target":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.4301775148,"explanation":"Airbus A380: 72.7 m (overall aircraft length). Washington Monument: 169 m (rounded monument height).\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-131","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros","measure":"4 m"},"bounds":[0.002,1.4],"answer":0.039,"explanation":"US dollar note: 0.156 m (approximate note length). White rhinoceros: 4 m (upper adult length).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","https://animals.sandiegozoo.org/animals/rhinoceros"]},{"id":"size-v9-132","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.1515151515,"explanation":"Door: 2 m (reference height). Hubble telescope: 13.2 m (body length).\nA two-metre door reference; doors vary.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["Reference chosen for comparison: a two-metre door.","https://science.nasa.gov/mission/hubble/observatory/design/"]},{"id":"size-v9-133","version":9,"kind":"scale","prompt":"How big is Washington Monument?","target":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.5121212121,"explanation":"Washington Monument: 169 m (rounded monument height). Eiffel Tower: 330 m (height, antenna included).\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-134","version":9,"kind":"scale","prompt":"How big is Saturn V?","target":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v"},"reference":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer","measure":"1600 m"},"bounds":[0.002,1.4],"answer":0.069125,"explanation":"Saturn V: 110.6 m (height with Apollo spacecraft). Imperial Star Destroyer: 1600 m (length).\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.","sources":["https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf","https://www.starwars.com/databank/imperial-star-destroyer/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',17,9,'[{"id":"size-v9-135","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.5866666667,"explanation":"Hubble telescope: 13.2 m (body length). AT-AT walker: 22.5 m (height).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-136","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.0497287523,"explanation":"Male giraffe: 5.5 m (upper adult height). Saturn V: 110.6 m (height with Apollo spacecraft).\nMale giraffes can reach about 5.5 m tall.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-137","version":9,"kind":"scale","prompt":"How big is Airbus A380?","target":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.657323689,"explanation":"Airbus A380: 72.7 m (overall aircraft length). Saturn V: 110.6 m (height with Apollo spacecraft).\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-138","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer","measure":"1600 m"},"bounds":[0.002,1.4],"answer":0.0209375,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). Imperial Star Destroyer: 1600 m (length).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.starwars.com/databank/imperial-star-destroyer/"]},{"id":"size-v9-139","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale","measure":"15.9 m"},"bounds":[0.002,1.4],"answer":0.1100628931,"explanation":"Person: 1.75 m (reference height). Male sperm whale: 15.9 m (mature adult length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nMature males reach about 52 ft (15.9 m); females are smaller.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.fisheries.noaa.gov/species/sperm-whale"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',18,9,'[{"id":"size-v9-140","version":9,"kind":"scale","prompt":"How big is Golf ball?","target":{"name":"Golf ball","dimension":"minimum permitted diameter","shape":"sourced:golf-ball"},"reference":{"name":"Door","dimension":"reference height","shape":"sourced:door","measure":"2 m"},"bounds":[0.002,1.4],"answer":0.021335,"explanation":"Golf ball: 0.04267 m (minimum permitted diameter). Door: 2 m (reference height).\nThe equipment rules set a minimum diameter of 42.67 mm. This board uses that minimum.\nA two-metre door reference; doors vary.","sources":["https://www.randa.org/roe/the-rules-of-equipment/part-4-conformance-of-balls","Reference chosen for comparison: a two-metre door."]},{"id":"size-v9-141","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.129046134,"explanation":"Tyrannosaurus rex: 12 m (adult length). Statue of Liberty: 92.99 m (height, pedestal included).\nAMNH gives an adult T. rex length of about 12 m.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-142","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.1100917431,"explanation":"Bus: 12 m (reference length). International Space Station: 109 m (end-to-end span).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-143","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.1724770642,"explanation":"Whale shark: 18.8 m (record measured length). International Space Station: 109 m (end-to-end span).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-144","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.1100917431,"explanation":"Tyrannosaurus rex: 12 m (adult length). International Space Station: 109 m (end-to-end span).\nAMNH gives an adult T. rex length of about 12 m.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',19,9,'[{"id":"size-v9-145","version":9,"kind":"scale","prompt":"How big is Statue of Liberty?","target":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.4843229167,"explanation":"Statue of Liberty: 92.99 m (height, pedestal included). Gateway Arch: 192 m (height above ground).\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-146","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.2045454545,"explanation":"Polar bear: 2.7 m (upper usual body length). Hubble telescope: 13.2 m (body length).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","https://science.nasa.gov/mission/hubble/observatory/design/"]},{"id":"size-v9-147","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.0503597122,"explanation":"Person: 1.75 m (reference height). Millennium Falcon: 34.75 m (overall length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-148","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale","measure":"15.9 m"},"bounds":[0.002,1.4],"answer":0.1257861635,"explanation":"Door: 2 m (reference height). Male sperm whale: 15.9 m (mature adult length).\nA two-metre door reference; doors vary.\nMature males reach about 52 ft (15.9 m); females are smaller.","sources":["Reference chosen for comparison: a two-metre door.","https://www.fisheries.noaa.gov/species/sperm-whale"]},{"id":"size-v9-149","version":9,"kind":"scale","prompt":"How big is Statue of Liberty?","target":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.8531192661,"explanation":"Statue of Liberty: 92.99 m (height, pedestal included). International Space Station: 109 m (end-to-end span).\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',20,9,'[{"id":"size-v9-150","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.043015378,"explanation":"White rhinoceros: 4 m (upper adult length). Statue of Liberty: 92.99 m (height, pedestal included).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-151","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.2222222222,"explanation":"Hippopotamus: 5 m (upper adult length). AT-AT walker: 22.5 m (height).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://animals.sandiegozoo.org/animals/hippo","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-152","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion","measure":"3.55 m"},"bounds":[0.002,1.4],"answer":0.5633802817,"explanation":"Door: 2 m (reference height). Male lion: 3.55 m (large adult length, tail included).\nA two-metre door reference; doors vary.\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.","sources":["Reference chosen for comparison: a two-metre door.","https://animals.sandiegozoo.org/animals/lion"]},{"id":"size-v9-153","version":9,"kind":"scale","prompt":"How big is Doubles tennis court?","target":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.1406508876,"explanation":"Doubles tennis court: 23.77 m (baseline-to-baseline length). Washington Monument: 169 m (rounded monument height).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-154","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0210059172,"explanation":"Male lion: 3.55 m (large adult length, tail included). Washington Monument: 169 m (rounded monument height).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://animals.sandiegozoo.org/animals/lion","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',21,9,'[{"id":"size-v9-155","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.1582733813,"explanation":"Male giraffe: 5.5 m (upper adult height). Millennium Falcon: 34.75 m (overall length).\nMale giraffes can reach about 5.5 m tall.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-156","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.4575539568,"explanation":"Male sperm whale: 15.9 m (mature adult length). Millennium Falcon: 34.75 m (overall length).\nMature males reach about 52 ft (15.9 m); females are smaller.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-157","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"Banana","dimension":"reference length","shape":"sourced:banana","measure":"0.18 m"},"bounds":[0.002,1.4],"answer":0.8666666667,"explanation":"US dollar note: 0.156 m (approximate note length). Banana: 0.18 m (reference length).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nAn 18 cm banana reference. Real bananas vary.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","Reference chosen for comparison: an 18 cm banana."]},{"id":"size-v9-158","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.1982248521,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). Washington Monument: 169 m (rounded monument height).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-159","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale","measure":"33.5 m"},"bounds":[0.002,1.4],"answer":0.3582089552,"explanation":"Bus: 12 m (reference length). Antarctic blue whale: 33.5 m (upper adult length).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.fisheries.noaa.gov/species/blue-whale"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',22,9,'[{"id":"size-v9-160","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0325443787,"explanation":"Male giraffe: 5.5 m (upper adult height). Washington Monument: 169 m (rounded monument height).\nMale giraffes can reach about 5.5 m tall.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-161","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.0481818182,"explanation":"Male sperm whale: 15.9 m (mature adult length). Eiffel Tower: 330 m (height, antenna included).\nMature males reach about 52 ft (15.9 m); females are smaller.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-162","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex","measure":"12 m"},"bounds":[0.002,1.4],"answer":1.1,"explanation":"Hubble telescope: 13.2 m (body length). Tyrannosaurus rex: 12 m (adult length).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nAMNH gives an adult T. rex length of about 12 m.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size"]},{"id":"size-v9-163","version":9,"kind":"scale","prompt":"How big is Airbus A380?","target":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.6669724771,"explanation":"Airbus A380: 72.7 m (overall aircraft length). International Space Station: 109 m (end-to-end span).\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-164","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.303030303,"explanation":"White rhinoceros: 4 m (upper adult length). Hubble telescope: 13.2 m (body length).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://science.nasa.gov/mission/hubble/observatory/design/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',23,9,'[{"id":"size-v9-165","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.06875,"explanation":"Hubble telescope: 13.2 m (body length). Gateway Arch: 192 m (height above ground).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-166","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"Door","dimension":"reference height","shape":"sourced:door","measure":"2 m"},"bounds":[0.002,1.4],"answer":1.35,"explanation":"Polar bear: 2.7 m (upper usual body length). Door: 2 m (reference height).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nA two-metre door reference; doors vary.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","Reference chosen for comparison: a two-metre door."]},{"id":"size-v9-167","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0710059172,"explanation":"Tyrannosaurus rex: 12 m (adult length). Washington Monument: 169 m (rounded monument height).\nAMNH gives an adult T. rex length of about 12 m.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-168","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0295857988,"explanation":"Hippopotamus: 5 m (upper adult length). Washington Monument: 169 m (rounded monument height).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://animals.sandiegozoo.org/animals/hippo","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-169","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.3071098023,"explanation":"African elephant: 7.3 m (upper adult length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',24,9,'[{"id":"size-v9-170","version":9,"kind":"scale","prompt":"How big is International Space Station?","target":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.5677083333,"explanation":"International Space Station: 109 m (end-to-end span). Gateway Arch: 192 m (height above ground).\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.nasa.gov/international-space-station/space-station-facts-and-figures/","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-171","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.2064220183,"explanation":"AT-AT walker: 22.5 m (height). International Space Station: 109 m (end-to-end span).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.starwars.com/databank/at-at-walker","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-172","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.0504587156,"explanation":"Male giraffe: 5.5 m (upper adult height). International Space Station: 109 m (end-to-end span).\nMale giraffes can reach about 5.5 m tall.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-173","version":9,"kind":"scale","prompt":"How big is Banana?","target":{"name":"Banana","dimension":"reference length","shape":"sourced:banana"},"reference":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros","measure":"4 m"},"bounds":[0.002,1.4],"answer":0.045,"explanation":"Banana: 0.18 m (reference length). White rhinoceros: 4 m (upper adult length).\nAn 18 cm banana reference. Real bananas vary.\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.","sources":["Reference chosen for comparison: an 18 cm banana.","https://animals.sandiegozoo.org/animals/rhinoceros"]},{"id":"size-v9-174","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.0575539568,"explanation":"Door: 2 m (reference height). Millennium Falcon: 34.75 m (overall length).\nA two-metre door reference; doors vary.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["Reference chosen for comparison: a two-metre door.","https://www.starwars.com/databank/millennium-falcon"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',25,9,'[{"id":"size-v9-175","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.3602537907,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). Statue of Liberty: 92.99 m (height, pedestal included).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-176","version":9,"kind":"scale","prompt":"How big is Saturn V?","target":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.5760416667,"explanation":"Saturn V: 110.6 m (height with Apollo spacecraft). Gateway Arch: 192 m (height above ground).\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-177","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.07565337,"explanation":"Male giraffe: 5.5 m (upper adult height). Airbus A380: 72.7 m (overall aircraft length).\nMale giraffes can reach about 5.5 m tall.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-178","version":9,"kind":"scale","prompt":"How big is US quarter?","target":{"name":"US quarter","dimension":"coin diameter","shape":"sourced:quarter"},"reference":{"name":"Golf ball","dimension":"minimum permitted diameter","shape":"sourced:golf-ball","measure":"0.04267 m"},"bounds":[0.002,1.4],"answer":0.5685493321,"explanation":"US quarter: 0.02426 m (coin diameter). Golf ball: 0.04267 m (minimum permitted diameter).\nA US quarter has a diameter of 24.26 mm. The profile represents the coin’s outline.\nThe equipment rules set a minimum diameter of 42.67 mm. This board uses that minimum.","sources":["https://www.usmint.gov/learn/coins-and-medals/circulating-coins/coin-specifications","https://www.randa.org/roe/the-rules-of-equipment/part-4-conformance-of-balls"]},{"id":"size-v9-179","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.0221212121,"explanation":"African elephant: 7.3 m (upper adult length). Eiffel Tower: 330 m (height, antenna included).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.toureiffel.paris/en/the-monument/key-figures"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',26,9,'[{"id":"size-v9-180","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.0325688073,"explanation":"Male lion: 3.55 m (large adult length, tail included). International Space Station: 109 m (end-to-end span).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://animals.sandiegozoo.org/animals/lion","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-181","version":9,"kind":"scale","prompt":"How big is Doubles tennis court?","target":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.684028777,"explanation":"Doubles tennis court: 23.77 m (baseline-to-baseline length). Millennium Falcon: 34.75 m (overall length).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-182","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.0660036166,"explanation":"African elephant: 7.3 m (upper adult length). Saturn V: 110.6 m (height with Apollo spacecraft).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-183","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark","measure":"18.8 m"},"bounds":[0.002,1.4],"answer":0.1063829787,"explanation":"Door: 2 m (reference height). Whale shark: 18.8 m (record measured length).\nA two-metre door reference; doors vary.\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.","sources":["Reference chosen for comparison: a two-metre door.","https://www.georgiaaquarium.org/animal/whale-shark/"]},{"id":"size-v9-184","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"Person","dimension":"reference height","shape":"sourced:human","measure":"1.75 m"},"bounds":[0.002,1.4],"answer":0.0891428571,"explanation":"US dollar note: 0.156 m (approximate note length). Person: 1.75 m (reference height).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nThe person is a fixed 1.75 m reference, not a claim about average human height.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","Reference chosen for comparison: a 1.75 m person."]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',27,9,'[{"id":"size-v9-185","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.5410071942,"explanation":"Whale shark: 18.8 m (record measured length). Millennium Falcon: 34.75 m (overall length).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-186","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.0888888889,"explanation":"Door: 2 m (reference height). AT-AT walker: 22.5 m (height).\nA two-metre door reference; doors vary.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["Reference chosen for comparison: a two-metre door.","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-187","version":9,"kind":"scale","prompt":"How big is Male lion?","target":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.1493479175,"explanation":"Male lion: 3.55 m (large adult length, tail included). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://animals.sandiegozoo.org/animals/lion","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-188","version":9,"kind":"scale","prompt":"How big is Humpback whale?","target":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale"},"reference":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon","measure":"34.75 m"},"bounds":[0.002,1.4],"answer":0.526618705,"explanation":"Humpback whale: 18.3 m (upper adult length). Millennium Falcon: 34.75 m (overall length).\nHumpbacks can reach about 60 ft (18.3 m).\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.","sources":["https://www.fisheries.noaa.gov/species/humpback-whale","https://www.starwars.com/databank/millennium-falcon"]},{"id":"size-v9-189","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0431952663,"explanation":"African elephant: 7.3 m (upper adult length). Washington Monument: 169 m (rounded monument height).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',28,9,'[{"id":"size-v9-190","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.3073394495,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). International Space Station: 109 m (end-to-end span).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-191","version":9,"kind":"scale","prompt":"How big is Banana?","target":{"name":"Banana","dimension":"reference length","shape":"sourced:banana"},"reference":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion","measure":"3.55 m"},"bounds":[0.002,1.4],"answer":0.0507042254,"explanation":"Banana: 0.18 m (reference length). Male lion: 3.55 m (large adult length, tail included).\nAn 18 cm banana reference. Real bananas vary.\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.","sources":["Reference chosen for comparison: an 18 cm banana.","https://animals.sandiegozoo.org/animals/lion"]},{"id":"size-v9-192","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus","measure":"5 m"},"bounds":[0.002,1.4],"answer":0.35,"explanation":"Person: 1.75 m (reference height). Hippopotamus: 5 m (upper adult length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nHippos measure about 3.3–5 m long. This board uses the upper end.","sources":["Reference chosen for comparison: a 1.75 m person.","https://animals.sandiegozoo.org/animals/hippo"]},{"id":"size-v9-193","version":9,"kind":"scale","prompt":"How big is International Space Station?","target":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.6449704142,"explanation":"International Space Station: 109 m (end-to-end span). Washington Monument: 169 m (rounded monument height).\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.nasa.gov/international-space-station/space-station-facts-and-figures/","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-194","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":1.2045454545,"explanation":"Male sperm whale: 15.9 m (mature adult length). Hubble telescope: 13.2 m (body length).\nMature males reach about 52 ft (15.9 m); females are smaller.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://science.nasa.gov/mission/hubble/observatory/design/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',29,9,'[{"id":"size-v9-195","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0710059172,"explanation":"Bus: 12 m (reference length). Washington Monument: 169 m (rounded monument height).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-196","version":9,"kind":"scale","prompt":"How big is Male sperm whale?","target":{"name":"Male sperm whale","dimension":"mature adult length","shape":"sourced:sperm-whale"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.7066666667,"explanation":"Male sperm whale: 15.9 m (mature adult length). AT-AT walker: 22.5 m (height).\nMature males reach about 52 ft (15.9 m); females are smaller.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://www.fisheries.noaa.gov/species/sperm-whale","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-197","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.1650618982,"explanation":"Bus: 12 m (reference length). Airbus A380: 72.7 m (overall aircraft length).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-198","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.2313840976,"explanation":"Male giraffe: 5.5 m (upper adult height). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nMale giraffes can reach about 5.5 m tall.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-199","version":9,"kind":"scale","prompt":"How big is Airbus A380?","target":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380"},"reference":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer","measure":"1600 m"},"bounds":[0.002,1.4],"answer":0.0454375,"explanation":"Airbus A380: 72.7 m (overall aircraft length). Imperial Star Destroyer: 1600 m (length).\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.","sources":["https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf","https://www.starwars.com/databank/imperial-star-destroyer/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',30,9,'[{"id":"size-v9-200","version":9,"kind":"scale","prompt":"How big is Washington Monument?","target":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument"},"reference":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer","measure":"1600 m"},"bounds":[0.002,1.4],"answer":0.105625,"explanation":"Washington Monument: 169 m (rounded monument height). Imperial Star Destroyer: 1600 m (length).\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.","sources":["https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf","https://www.starwars.com/databank/imperial-star-destroyer/"]},{"id":"size-v9-201","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus","measure":"12 m"},"bounds":[0.002,1.4],"answer":0.4583333333,"explanation":"Male giraffe: 5.5 m (upper adult height). Bus: 12 m (reference length).\nMale giraffes can reach about 5.5 m tall.\nThe bus is a fixed 12 m reference; vehicle models have different lengths.","sources":["https://animals.sandiegozoo.org/animals/giraffe","Reference chosen for comparison: a 12 m bus."]},{"id":"size-v9-202","version":9,"kind":"scale","prompt":"How big is White rhinoceros?","target":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.0361663653,"explanation":"White rhinoceros: 4 m (upper adult length). Saturn V: 110.6 m (height with Apollo spacecraft).\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://animals.sandiegozoo.org/animals/rhinoceros","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]},{"id":"size-v9-203","version":9,"kind":"scale","prompt":"How big is AT-AT walker?","target":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.3094910591,"explanation":"AT-AT walker: 22.5 m (height). Airbus A380: 72.7 m (overall aircraft length).\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://www.starwars.com/databank/at-at-walker","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]},{"id":"size-v9-204","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus","measure":"12 m"},"bounds":[0.002,1.4],"answer":0.225,"explanation":"Polar bear: 2.7 m (upper usual body length). Bus: 12 m (reference length).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nThe bus is a fixed 12 m reference; vehicle models have different lengths.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","Reference chosen for comparison: a 12 m bus."]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',31,9,'[{"id":"size-v9-205","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.0537692225,"explanation":"Hippopotamus: 5 m (upper adult length). Statue of Liberty: 92.99 m (height, pedestal included).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://animals.sandiegozoo.org/animals/hippo","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-206","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.1112426036,"explanation":"Whale shark: 18.8 m (record measured length). Washington Monument: 169 m (rounded monument height).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-207","version":9,"kind":"scale","prompt":"How big is Golf ball?","target":{"name":"Golf ball","dimension":"minimum permitted diameter","shape":"sourced:golf-ball"},"reference":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note","measure":"0.156 m"},"bounds":[0.002,1.4],"answer":0.273525641,"explanation":"Golf ball: 0.04267 m (minimum permitted diameter). US dollar note: 0.156 m (approximate note length).\nThe equipment rules set a minimum diameter of 42.67 mm. This board uses that minimum.\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.","sources":["https://www.randa.org/roe/the-rules-of-equipment/part-4-conformance-of-balls","https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm"]},{"id":"size-v9-208","version":9,"kind":"scale","prompt":"How big is International Space Station?","target":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss"},"reference":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer","measure":"1600 m"},"bounds":[0.002,1.4],"answer":0.068125,"explanation":"International Space Station: 109 m (end-to-end span). Imperial Star Destroyer: 1600 m (length).\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.","sources":["https://www.nasa.gov/international-space-station/space-station-facts-and-figures/","https://www.starwars.com/databank/imperial-star-destroyer/"]},{"id":"size-v9-209","version":9,"kind":"scale","prompt":"How big is Doubles tennis court?","target":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.2180733945,"explanation":"Doubles tennis court: 23.77 m (baseline-to-baseline length). International Space Station: 109 m (end-to-end span).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',32,9,'[{"id":"size-v9-210","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.3244444444,"explanation":"African elephant: 7.3 m (upper adult length). AT-AT walker: 22.5 m (height).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-211","version":9,"kind":"scale","prompt":"How big is Banana?","target":{"name":"Banana","dimension":"reference length","shape":"sourced:banana"},"reference":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus","measure":"5 m"},"bounds":[0.002,1.4],"answer":0.036,"explanation":"Banana: 0.18 m (reference length). Hippopotamus: 5 m (upper adult length).\nAn 18 cm banana reference. Real bananas vary.\nHippos measure about 3.3–5 m long. This board uses the upper end.","sources":["Reference chosen for comparison: an 18 cm banana.","https://animals.sandiegozoo.org/animals/hippo"]},{"id":"size-v9-212","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale","measure":"18.3 m"},"bounds":[0.002,1.4],"answer":0.6557377049,"explanation":"Bus: 12 m (reference length). Humpback whale: 18.3 m (upper adult length).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nHumpbacks can reach about 60 ft (18.3 m).","sources":["Reference chosen for comparison: a 12 m bus.","https://www.fisheries.noaa.gov/species/humpback-whale"]},{"id":"size-v9-213","version":9,"kind":"scale","prompt":"How big is Millennium Falcon?","target":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.1809895833,"explanation":"Millennium Falcon: 34.75 m (overall length). Gateway Arch: 192 m (height above ground).\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.starwars.com/databank/millennium-falcon","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-214","version":9,"kind":"scale","prompt":"How big is Male giraffe?","target":{"name":"Male giraffe","dimension":"upper adult height","shape":"sourced:giraffe"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.4166666667,"explanation":"Male giraffe: 5.5 m (upper adult height). Hubble telescope: 13.2 m (body length).\nMale giraffes can reach about 5.5 m tall.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://animals.sandiegozoo.org/animals/giraffe","https://science.nasa.gov/mission/hubble/observatory/design/"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',33,9,'[{"id":"size-v9-215","version":9,"kind":"scale","prompt":"How big is Airbus A380?","target":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.7818044951,"explanation":"Airbus A380: 72.7 m (overall aircraft length). Statue of Liberty: 92.99 m (height, pedestal included).\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-216","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale","measure":"33.5 m"},"bounds":[0.002,1.4],"answer":0.0597014925,"explanation":"Door: 2 m (reference height). Antarctic blue whale: 33.5 m (upper adult length).\nA two-metre door reference; doors vary.\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.","sources":["Reference chosen for comparison: a two-metre door.","https://www.fisheries.noaa.gov/species/blue-whale"]},{"id":"size-v9-217","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.0736222129,"explanation":"Person: 1.75 m (reference height). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-218","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion","measure":"3.55 m"},"bounds":[0.002,1.4],"answer":0.043943662,"explanation":"US dollar note: 0.156 m (approximate note length). Male lion: 3.55 m (large adult length, tail included).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","https://animals.sandiegozoo.org/animals/lion"]},{"id":"size-v9-219","version":9,"kind":"scale","prompt":"How big is Doubles tennis court?","target":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.072030303,"explanation":"Doubles tennis court: 23.77 m (baseline-to-baseline length). Eiffel Tower: 330 m (height, antenna included).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf","https://www.toureiffel.paris/en/the-monument/key-figures"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',34,9,'[{"id":"size-v9-220","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex","measure":"12 m"},"bounds":[0.002,1.4],"answer":0.1458333333,"explanation":"Person: 1.75 m (reference height). Tyrannosaurus rex: 12 m (adult length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nAMNH gives an adult T. rex length of about 12 m.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size"]},{"id":"size-v9-221","version":9,"kind":"scale","prompt":"How big is Millennium Falcon?","target":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.3736960964,"explanation":"Millennium Falcon: 34.75 m (overall length). Statue of Liberty: 92.99 m (height, pedestal included).\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.starwars.com/databank/millennium-falcon","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-222","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear","measure":"2.7 m"},"bounds":[0.002,1.4],"answer":0.6481481481,"explanation":"Person: 1.75 m (reference height). Polar bear: 2.7 m (upper usual body length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.","sources":["Reference chosen for comparison: a 1.75 m person.","https://animals.sandiegozoo.org/animals/polar-bear"]},{"id":"size-v9-223","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.0979166667,"explanation":"Whale shark: 18.8 m (record measured length). Gateway Arch: 192 m (height above ground).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-224","version":9,"kind":"scale","prompt":"How big is Death Star I?","target":{"name":"Death Star I","dimension":"equatorial diameter","shape":"sourced:death-star"},"reference":{"name":"The Moon","dimension":"mean diameter","shape":"sourced:moon","measure":"3.4748e+06 m"},"bounds":[0.002,1.4],"answer":0.0460458156,"explanation":"Death Star I: 160000 m (equatorial diameter). The Moon: 3.4748e+06 m (mean diameter).\nThe first Death Star in A New Hope: the current official reference gives a diameter of 160 km. Fictional.\nThe Moon’s mean diameter is about 3,474.8 km.","sources":["https://www.starwars.com/news/star-wars-inside-intel-the-death-star","https://science.nasa.gov/wp-content/uploads/2023/05/ladee-press-kit-08292013.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',35,9,'[{"id":"size-v9-225","version":9,"kind":"scale","prompt":"How big is African elephant?","target":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant"},"reference":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble","measure":"13.2 m"},"bounds":[0.002,1.4],"answer":0.553030303,"explanation":"African elephant: 7.3 m (upper adult length). Hubble telescope: 13.2 m (body length).\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.\nHubble is about 13.2 m long; solar panels extend to either side of its body.","sources":["https://www.worldwildlife.org/species/elephant/african-elephant/","https://science.nasa.gov/mission/hubble/observatory/design/"]},{"id":"size-v9-226","version":9,"kind":"scale","prompt":"How big is Antarctic blue whale?","target":{"name":"Antarctic blue whale","dimension":"upper adult length","shape":"sourced:blue-whale"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.1015151515,"explanation":"Antarctic blue whale: 33.5 m (upper adult length). Eiffel Tower: 330 m (height, antenna included).\nAntarctic blue whales can reach about 110 ft (33.5 m); other populations are smaller.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.fisheries.noaa.gov/species/blue-whale","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-227","version":9,"kind":"scale","prompt":"How big is International Space Station?","target":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.3303030303,"explanation":"International Space Station: 109 m (end-to-end span). Eiffel Tower: 330 m (height, antenna included).\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.nasa.gov/international-space-station/space-station-facts-and-figures/","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-228","version":9,"kind":"scale","prompt":"How big is Humpback whale?","target":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale"},"reference":{"name":"International Space Station","dimension":"end-to-end span","shape":"sourced:iss","measure":"109 m"},"bounds":[0.002,1.4],"answer":0.1678899083,"explanation":"Humpback whale: 18.3 m (upper adult length). International Space Station: 109 m (end-to-end span).\nHumpbacks can reach about 60 ft (18.3 m).\nNASA gives the station an end-to-end span of about 109 m. The diagram is a simplified plan view.","sources":["https://www.fisheries.noaa.gov/species/humpback-whale","https://www.nasa.gov/international-space-station/space-station-facts-and-figures/"]},{"id":"size-v9-229","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.0240715268,"explanation":"Person: 1.75 m (reference height). Airbus A380: 72.7 m (overall aircraft length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',36,9,'[{"id":"size-v9-230","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"AT-AT walker","dimension":"height","shape":"sourced:at-at","measure":"22.5 m"},"bounds":[0.002,1.4],"answer":0.5333333333,"explanation":"Bus: 12 m (reference length). AT-AT walker: 22.5 m (height).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nThe original Imperial AT-AT stands 22.5 m tall. Fictional.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.starwars.com/databank/at-at-walker"]},{"id":"size-v9-231","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.2103491796,"explanation":"Hippopotamus: 5 m (upper adult length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://animals.sandiegozoo.org/animals/hippo","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-232","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.113588557,"explanation":"Polar bear: 2.7 m (upper usual body length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-233","version":9,"kind":"scale","prompt":"How big is Doubles tennis court?","target":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.2556188838,"explanation":"Doubles tennis court: 23.77 m (baseline-to-baseline length). Statue of Liberty: 92.99 m (height, pedestal included).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-234","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"Saturn V","dimension":"height with Apollo spacecraft","shape":"sourced:saturn-v","measure":"110.6 m"},"bounds":[0.002,1.4],"answer":0.0244122966,"explanation":"Polar bear: 2.7 m (upper usual body length). Saturn V: 110.6 m (height with Apollo spacecraft).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nNASA lists the complete Apollo–Saturn V at 363 ft (110.6 m).","sources":["https://animals.sandiegozoo.org/animals/polar-bear","https://www.nasa.gov/wp-content/uploads/2015/03/167718main_early_years.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',37,9,'[{"id":"size-v9-235","version":9,"kind":"scale","prompt":"How big is US dollar note?","target":{"name":"US dollar note","dimension":"approximate note length","shape":"sourced:dollar-note"},"reference":{"name":"Door","dimension":"reference height","shape":"sourced:door","measure":"2 m"},"bounds":[0.002,1.4],"answer":0.078,"explanation":"US dollar note: 0.156 m (approximate note length). Door: 2 m (reference height).\nModern US currency notes are approximately 6.14 inches long, or 15.6 cm.\nA two-metre door reference; doors vary.","sources":["https://www.federalreserve.gov/aboutthefed/chapter-1-balance-sheet.htm","Reference chosen for comparison: a two-metre door."]},{"id":"size-v9-236","version":9,"kind":"scale","prompt":"How big is Bus?","target":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus"},"reference":{"name":"Gateway Arch","dimension":"height above ground","shape":"sourced:gateway-arch","measure":"192 m"},"bounds":[0.002,1.4],"answer":0.0625,"explanation":"Bus: 12 m (reference length). Gateway Arch: 192 m (height above ground).\nThe bus is a fixed 12 m reference; vehicle models have different lengths.\nThe arch is about 192 m tall and approximately the same width from leg to leg.","sources":["Reference chosen for comparison: a 12 m bus.","https://www.nps.gov/jeff/faqs.htm"]},{"id":"size-v9-237","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Washington Monument","dimension":"rounded monument height","shape":"sourced:washington-monument","measure":"169 m"},"bounds":[0.002,1.4],"answer":0.0781065089,"explanation":"Hubble telescope: 13.2 m (body length). Washington Monument: 169 m (rounded monument height).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nThe National Park Service rounds the obelisk’s height to 169 m in this educational reference.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.nps.gov/articles/000/upload/Build-Your-Own-Washington-Monument-Activity.pdf"]},{"id":"size-v9-238","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Male lion","dimension":"large adult length, tail included","shape":"sourced:lion","measure":"3.55 m"},"bounds":[0.002,1.4],"answer":0.4929577465,"explanation":"Person: 1.75 m (reference height). Male lion: 3.55 m (large adult length, tail included).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nA large male has up to 2.5 m of head and body, plus up to 1.05 m of tail; this illustrative upper-end total is 3.55 m.","sources":["Reference chosen for comparison: a 1.75 m person.","https://animals.sandiegozoo.org/animals/lion"]},{"id":"size-v9-239","version":9,"kind":"scale","prompt":"How big is Door?","target":{"name":"Door","dimension":"reference height","shape":"sourced:door"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.0275103164,"explanation":"Door: 2 m (reference height). Airbus A380: 72.7 m (overall aircraft length).\nA two-metre door reference; doors vary.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["Reference chosen for comparison: a two-metre door.","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',38,9,'[{"id":"size-v9-240","version":9,"kind":"scale","prompt":"How big is Statue of Liberty?","target":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty"},"reference":{"name":"Imperial Star Destroyer","dimension":"length","shape":"sourced:star-destroyer","measure":"1600 m"},"bounds":[0.002,1.4],"answer":0.05811875,"explanation":"Statue of Liberty: 92.99 m (height, pedestal included). Imperial Star Destroyer: 1600 m (length).\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.\nThe classic Imperial Star Destroyer is 1,600 m long. Fictional; shown from above.","sources":["https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm","https://www.starwars.com/databank/imperial-star-destroyer/"]},{"id":"size-v9-241","version":9,"kind":"scale","prompt":"How big is Millennium Falcon?","target":{"name":"Millennium Falcon","dimension":"overall length","shape":"sourced:falcon"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.1053030303,"explanation":"Millennium Falcon: 34.75 m (overall length). Eiffel Tower: 330 m (height, antenna included).\nThe Millennium Falcon is 34.75 m long in the official databank. Fictional; shown from above.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.starwars.com/databank/millennium-falcon","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-242","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark","measure":"18.8 m"},"bounds":[0.002,1.4],"answer":0.0930851064,"explanation":"Person: 1.75 m (reference height). Whale shark: 18.8 m (record measured length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.georgiaaquarium.org/animal/whale-shark/"]},{"id":"size-v9-243","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"African elephant","dimension":"upper adult length","shape":"sourced:african-elephant","measure":"7.3 m"},"bounds":[0.002,1.4],"answer":0.2397260274,"explanation":"Person: 1.75 m (reference height). African elephant: 7.3 m (upper adult length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nWWF gives a length range of 19–24 ft (5.8–7.3 m). This board uses the upper end, with the trunk hanging down.","sources":["Reference chosen for comparison: a 1.75 m person.","https://www.worldwildlife.org/species/elephant/african-elephant/"]},{"id":"size-v9-244","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.5553218342,"explanation":"Hubble telescope: 13.2 m (body length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',39,9,'[{"id":"size-v9-245","version":9,"kind":"scale","prompt":"How big is Polar bear?","target":{"name":"Polar bear","dimension":"upper usual body length","shape":"sourced:polar-bear"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.0290353801,"explanation":"Polar bear: 2.7 m (upper usual body length). Statue of Liberty: 92.99 m (height, pedestal included).\nSan Diego Zoo gives a usual head-and-body length of 1.8–2.7 m. This board uses 2.7 m; the small tail is not part of that measurement.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://animals.sandiegozoo.org/animals/polar-bear","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-246","version":9,"kind":"scale","prompt":"How big is Person?","target":{"name":"Person","dimension":"reference height","shape":"sourced:human"},"reference":{"name":"White rhinoceros","dimension":"upper adult length","shape":"sourced:rhinoceros","measure":"4 m"},"bounds":[0.002,1.4],"answer":0.4375,"explanation":"Person: 1.75 m (reference height). White rhinoceros: 4 m (upper adult length).\nThe person is a fixed 1.75 m reference, not a claim about average human height.\nWhite rhinos are about 3.7–4 m long. This board uses the upper end.","sources":["Reference chosen for comparison: a 1.75 m person.","https://animals.sandiegozoo.org/animals/rhinoceros"]},{"id":"size-v9-247","version":9,"kind":"scale","prompt":"How big is Humpback whale?","target":{"name":"Humpback whale","dimension":"upper adult length","shape":"sourced:humpback-whale"},"reference":{"name":"Doubles tennis court","dimension":"baseline-to-baseline length","shape":"sourced:tennis-court","measure":"23.77 m"},"bounds":[0.002,1.4],"answer":0.7698779975,"explanation":"Humpback whale: 18.3 m (upper adult length). Doubles tennis court: 23.77 m (baseline-to-baseline length).\nHumpbacks can reach about 60 ft (18.3 m).\nThe playing court is 23.77 m long. Run-off space beyond the lines is excluded.","sources":["https://www.fisheries.noaa.gov/species/humpback-whale","https://www.itftennis.com/media/7221/2024-rules-of-tennis-english.pdf"]},{"id":"size-v9-248","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Eiffel Tower","dimension":"height, antenna included","shape":"sourced:eiffel-tower","measure":"330 m"},"bounds":[0.002,1.4],"answer":0.0363636364,"explanation":"Tyrannosaurus rex: 12 m (adult length). Eiffel Tower: 330 m (height, antenna included).\nAMNH gives an adult T. rex length of about 12 m.\nThe Eiffel Tower is 330 m tall including its antenna.","sources":["https://www.amnh.org/exhibitions/dinosaurs-ancient-fossils/theropod-biomechanics/the-problem-of-size","https://www.toureiffel.paris/en/the-monument/key-figures"]},{"id":"size-v9-249","version":9,"kind":"scale","prompt":"How big is Whale shark?","target":{"name":"Whale shark","dimension":"record measured length","shape":"sourced:whale-shark"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.2585969739,"explanation":"Whale shark: 18.8 m (record measured length). Airbus A380: 72.7 m (overall aircraft length).\nGeorgia Aquarium reports a largest measured whale shark of 18.8 m. Common adults are much smaller: 5.5–10 m.\nAirbus gives the A380 an overall length of 72.7 m. This is a side profile, not its wingspan.","sources":["https://www.georgiaaquarium.org/animal/whale-shark/","https://www.airbus.com/sites/g/files/jlcbta136/files/2025-01/airbus-a380-facts-and-figures-february-2022.pdf"]}]'::jsonb);
INSERT INTO ledger_private.trivia_packs(game,slot,version,questions) VALUES('how-much-ish',40,9,'[{"id":"size-v9-250","version":9,"kind":"scale","prompt":"How big is Hubble telescope?","target":{"name":"Hubble telescope","dimension":"body length","shape":"sourced:hubble"},"reference":{"name":"Statue of Liberty","dimension":"height, pedestal included","shape":"sourced:statue-of-liberty","measure":"92.99 m"},"bounds":[0.002,1.4],"answer":0.1419507474,"explanation":"Hubble telescope: 13.2 m (body length). Statue of Liberty: 92.99 m (height, pedestal included).\nHubble is about 13.2 m long; solar panels extend to either side of its body.\nThe full monument measures 92.99 m from ground to torch, including the pedestal. The statue alone is 46.05 m.","sources":["https://science.nasa.gov/mission/hubble/observatory/design/","https://www.nps.gov/stli/learn/historyculture/statue-statistics.htm"]},{"id":"size-v9-251","version":9,"kind":"scale","prompt":"How big is Hippopotamus?","target":{"name":"Hippopotamus","dimension":"upper adult length","shape":"sourced:hippopotamus"},"reference":{"name":"Bus","dimension":"reference length","shape":"sourced:school-bus","measure":"12 m"},"bounds":[0.002,1.4],"answer":0.4166666667,"explanation":"Hippopotamus: 5 m (upper adult length). Bus: 12 m (reference length).\nHippos measure about 3.3–5 m long. This board uses the upper end.\nThe bus is a fixed 12 m reference; vehicle models have different lengths.","sources":["https://animals.sandiegozoo.org/animals/hippo","Reference chosen for comparison: a 12 m bus."]},{"id":"size-v9-50","version":9,"kind":"scale","prompt":"How big is Tyrannosaurus rex?","target":{"name":"Tyrannosaurus rex","dimension":"adult length","shape":"sourced:t-rex"},"reference":{"name":"Airbus A380","dimension":"overall aircraft length","shape":"sourced:a380","measure":"72.7 m"},"bounds":[0.002,1.4],"answer":0.1650618982,"explanation":"Tyrannosaurus rex: 12 m (adult length). Airbus A380: 72.7 m (overall aircraft length).\nA